async function handleListConversations(
  ws: WebSocket,
  sessionStore: SessionStore,
  historyConfig: {enabled: boolean} | undefined,
  message: import('../../types/messages.js').ListConversationsMessage
): Promise<void> {
  const userId = (ws as any).userId;

  if (!historyConfig?.enabled || !sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(userId, {limit: message.limit, before: message.before});
    sendConversationList(
      ws,
      summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      }))
    );
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not supported by the current store');
      return;
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'list_conversations failed', {userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

